"use strict";(globalThis.webpackChunkc_users_ksabando_app_data_local_temp_docusaurus_init=globalThis.webpackChunkc_users_ksabando_app_data_local_temp_docusaurus_init||[]).push([[64517],{16222(e,n,a){a.r(n),a.d(n,{assets:()=>t,contentTitle:()=>c,default:()=>p,frontMatter:()=>r,metadata:()=>o,toc:()=>d});const o=JSON.parse('{"id":"cursos/solid/modulos/dip-dependency-inversion/cuestionario","title":"cuestionario","description":"2. [Investigar] \xbfCu\xe1l es la diferencia entre Inversion of Control (IoC) como principio general y DIP como principio de dise\xf1o? Investig\xe1 los or\xedgenes de IoC (Martin Fowler, 2004 - \\"Inversion of Control Containers and the Dependency Injection Pattern\\") y explic\xe1 c\xf3mo el \\"Hollywood Principle\\" (\\"Don\'t call us, we\'ll call you\\") es IoC pero no necesariamente DIP.","source":"@site/docs/cursos/solid/modulos/06-dip-dependency-inversion/cuestionario.md","sourceDirName":"cursos/solid/modulos/06-dip-dependency-inversion","slug":"/cursos/solid/modulos/dip-dependency-inversion/cuestionario","permalink":"/sasf-temarios/cursos/solid/modulos/dip-dependency-inversion/cuestionario","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"private":true,"sidebar_class_name":"private","sidebar_label":"Cuestionario"},"sidebar":"cursosSidebar","previous":{"title":"Clase","permalink":"/sasf-temarios/cursos/solid/modulos/dip-dependency-inversion/clase"},"next":{"title":"Ejercicio","permalink":"/sasf-temarios/cursos/solid/modulos/dip-dependency-inversion/ejercicio"}}');var i=a(74848),s=a(28453);const r={private:!0,sidebar_class_name:"private",sidebar_label:"Cuestionario"},c=void 0,t={},d=[{value:"2. [Investigar] \xbfCu\xe1l es la diferencia entre Inversion of Control (IoC) como principio general y DIP como principio de dise\xf1o? Investig\xe1 los or\xedgenes de IoC (Martin Fowler, 2004 - &quot;Inversion of Control Containers and the Dependency Injection Pattern&quot;) y explic\xe1 c\xf3mo el &quot;Hollywood Principle&quot; (&quot;Don&#39;t call us, we&#39;ll call you&quot;) es IoC pero no necesariamente DIP.",id:"2-investigar-cu\xe1l-es-la-diferencia-entre-inversion-of-control-ioc-como-principio-general-y-dip-como-principio-de-dise\xf1o-investig\xe1-los-or\xedgenes-de-ioc-martin-fowler-2004---inversion-of-control-containers-and-the-dependency-injection-pattern-y-explic\xe1-c\xf3mo-el-hollywood-principle-dont-call-us-well-call-you-es-ioc-pero-no-necesariamente-dip",level:3},{value:"3. [Investigar] \xbfC\xf3mo se aplica DIP en programaci\xf3n funcional? Investig\xe1 c\xf3mo los lenguajes funcionales logran inversi\xf3n de dependencias mediante higher-order functions, type classes (Haskell/Scala), y el &quot;Reader monad&quot; pattern. \xbfSon estos mecanismos m\xe1s o menos poderosos que las interfaces en OOP?",id:"3-investigar-c\xf3mo-se-aplica-dip-en-programaci\xf3n-funcional-investig\xe1-c\xf3mo-los-lenguajes-funcionales-logran-inversi\xf3n-de-dependencias-mediante-higher-order-functions-type-classes-haskellscala-y-el-reader-monad-pattern-son-estos-mecanismos-m\xe1s-o-menos-poderosos-que-las-interfaces-en-oop",level:3},{value:"4. [Investigar] \xbfC\xf3mo funciona el Service Provider Interface (SPI) de Java y c\xf3mo se relaciona con DIP? Investig\xe1 java.util.ServiceLoader (Java 6+) y el mecanismo de providers en Java 9+ modules. \xbfEn qu\xe9 se diferencia SPI de DI para implementar DIP?",id:"4-investigar-c\xf3mo-funciona-el-service-provider-interface-spi-de-java-y-c\xf3mo-se-relaciona-con-dip-investig\xe1-javautilserviceloader-java-6-y-el-mecanismo-de-providers-en-java-9-modules-en-qu\xe9-se-diferencia-spi-de-di-para-implementar-dip",level:3},{value:"5. [Conectar] La clase menciona que DIP habilita la arquitectura hexagonal (Ports &amp; Adapters). Investig\xe1 a fondo el trabajo original de Alistair Cockburn (2005) sobre Hexagonal Architecture y explic\xe1 c\xf3mo DIP es el &quot;pegamento&quot; que hace posible la inversi\xf3n de dependencias entre el dominio y la infraestructura.",id:"5-conectar-la-clase-menciona-que-dip-habilita-la-arquitectura-hexagonal-ports--adapters-investig\xe1-a-fondo-el-trabajo-original-de-alistair-cockburn-2005-sobre-hexagonal-architecture-y-explic\xe1-c\xf3mo-dip-es-el-pegamento-que-hace-posible-la-inversi\xf3n-de-dependencias-entre-el-dominio-y-la-infraestructura",level:3},{value:"6. [Conectar] Conect\xe1 DIP con el patr\xf3n &quot;Dependency Injection&quot; usando libraries en React. \xbfC\xf3mo el patr\xf3n de &quot;InversifyJS&quot; para TypeScript/React implementa IoC + DIP en frontend? Compar\xe1 con el enfoque de Context API de la clase.",id:"6-conectar-conect\xe1-dip-con-el-patr\xf3n-dependency-injection-usando-libraries-en-react-c\xf3mo-el-patr\xf3n-de-inversifyjs-para-typescriptreact-implementa-ioc--dip-en-frontend-compar\xe1-con-el-enfoque-de-context-api-de-la-clase",level:3},{value:"7. [Conectar] Relacion\xe1 DIP con el concepto de &quot;Test Doubles&quot; (Gerard Meszaros, &quot;xUnit Test Patterns&quot;, 2007). \xbfPor qu\xe9 sin DIP no pod\xe9s usar stubs, mocks o fakes efectivamente? Explic\xe1 c\xf3mo cada tipo de test double requiere un nivel diferente de DIP.",id:"7-conectar-relacion\xe1-dip-con-el-concepto-de-test-doubles-gerard-meszaros-xunit-test-patterns-2007-por-qu\xe9-sin-dip-no-pod\xe9s-usar-stubs-mocks-o-fakes-efectivamente-explic\xe1-c\xf3mo-cada-tipo-de-test-double-requiere-un-nivel-diferente-de-dip",level:3},{value:"8. [Cuestionar] \xbfEs DIP siempre beneficioso o puede llevar a una &quot;arquitectura de cebolla podrida&quot;? Investig\xe1 cr\xedticas sobre sistemas donde cada clase tiene una interfaz, cada m\xe9todo tiene una abstracci\xf3n, y el grafo de dependencias es tan complejo que entender el flujo requiere herramientas de visualizaci\xf3n. \xbfD\xf3nde est\xe1 el l\xedmite de la inversi\xf3n?",id:"8-cuestionar-es-dip-siempre-beneficioso-o-puede-llevar-a-una-arquitectura-de-cebolla-podrida-investig\xe1-cr\xedticas-sobre-sistemas-donde-cada-clase-tiene-una-interfaz-cada-m\xe9todo-tiene-una-abstracci\xf3n-y-el-grafo-de-dependencias-es-tan-complejo-que-entender-el-flujo-requiere-herramientas-de-visualizaci\xf3n-d\xf3nde-est\xe1-el-l\xedmite-de-la-inversi\xf3n",level:3},{value:"9. [Cuestionar] \xbfDIP o &quot;Service Locator&quot;? Martin Fowler (2004) argument\xf3 que Service Locator es un anti-patr\xf3n comparado con Dependency Injection. Pero frameworks como Android (con Hilt/Dagger) y algunos sistemas legacy usan Service Locator exitosamente. \xbfEs realmente un anti-patr\xf3n o una alternativa v\xe1lida en ciertos contextos?",id:"9-cuestionar-dip-o-service-locator-martin-fowler-2004-argument\xf3-que-service-locator-es-un-anti-patr\xf3n-comparado-con-dependency-injection-pero-frameworks-como-android-con-hiltdagger-y-algunos-sistemas-legacy-usan-service-locator-exitosamente-es-realmente-un-anti-patr\xf3n-o-una-alternativa-v\xe1lida-en-ciertos-contextos",level:3},{value:"10. [Cuestionar] \xbfEs DIP el principio m\xe1s &quot;costoso&quot; de SOLID? Investig\xe1 el trade-off entre inversi\xf3n de dependencias y performance/carga cognitiva. \xbfHay dominios (ej. sistemas embebidos, videojuegos, high-frequency trading) donde DIP activamente perjudica?",id:"10-cuestionar-es-dip-el-principio-m\xe1s-costoso-de-solid-investig\xe1-el-trade-off-entre-inversi\xf3n-de-dependencias-y-performancecarga-cognitiva-hay-dominios-ej-sistemas-embebidos-videojuegos-high-frequency-trading-donde-dip-activamente-perjudica",level:3}];function l(e){const n={code:"code",h3:"h3",hr:"hr",p:"p",strong:"strong",...(0,s.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(n.h3,{id:"2-investigar-cu\xe1l-es-la-diferencia-entre-inversion-of-control-ioc-como-principio-general-y-dip-como-principio-de-dise\xf1o-investig\xe1-los-or\xedgenes-de-ioc-martin-fowler-2004---inversion-of-control-containers-and-the-dependency-injection-pattern-y-explic\xe1-c\xf3mo-el-hollywood-principle-dont-call-us-well-call-you-es-ioc-pero-no-necesariamente-dip",children:'2. [Investigar] \xbfCu\xe1l es la diferencia entre Inversion of Control (IoC) como principio general y DIP como principio de dise\xf1o? Investig\xe1 los or\xedgenes de IoC (Martin Fowler, 2004 - "Inversion of Control Containers and the Dependency Injection Pattern") y explic\xe1 c\xf3mo el "Hollywood Principle" ("Don\'t call us, we\'ll call you") es IoC pero no necesariamente DIP.'}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"Respuesta"}),': Fowler populariz\xf3 IoC en 2004 describiendo c\xf3mo los frameworks invierten el flujo de control: tu c\xf3digo no controla el flujo principal; el framework lo hace. El "Hollywood Principle" es la personificaci\xf3n: no llames al framework; el framework te llamar\xe1 a vos. Diferencia con DIP: ',(0,i.jsx)(n.strong,{children:"IoC"})," es sobre QUI\xc9N controla el flujo de ejecuci\xf3n (framework vs tu c\xf3digo). ",(0,i.jsx)(n.strong,{children:"DIP"})," es sobre DE QU\xc9 dependen tus m\xf3dulos (abstracciones vs implementaciones). Ejemplos de IoC sin DIP: (1) Un servlet de Java donde ",(0,i.jsx)(n.code,{children:"doGet()"})," es llamado por el contenedor (IoC: el contenedor controla el flujo), pero el servlet usa ",(0,i.jsx)(n.code,{children:"new JdbcTemplate()"})," internamente (viola DIP). (2) Un callback de JavaScript donde ",(0,i.jsx)(n.code,{children:"button.onClick = myFunction"})," \u2014 el navegador llama a tu funci\xf3n (IoC), pero ",(0,i.jsx)(n.code,{children:"myFunction"})," puede depender de ",(0,i.jsx)(n.code,{children:"document.getElementById()"})," directamente (sin abstracci\xf3n). Ejemplo de DIP sin IoC: ",(0,i.jsx)(n.code,{children:'Database db = DatabaseFactory.create("postgres")'})," \u2014 ",(0,i.jsx)(n.code,{children:"db"})," es una interfaz (DIP), pero tu c\xf3digo instancia la f\xe1brica y controla el flujo (no IoC). El ideal como en Spring: el contenedor IoC inyecta dependencias abstractas (IoC + DIP juntos). Fowler enfatiza que DI es una forma espec\xedfica de IoC (la inyecci\xf3n de dependencias), pero IoC abarca m\xe1s (patrones, eventos, callbacks)."]}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"Por qu\xe9"}),': Fowler aclar\xf3 la confusi\xf3n en su art\xedculo de 2004: "Inversion of Control es un t\xe9rmino gen\xe9rico; Dependency Injection es la forma espec\xedfica de IoC que nos interesa para desacoplar componentes". DIP es el principio de dise\xf1o que DI implementa.']}),"\n",(0,i.jsx)(n.hr,{}),"\n",(0,i.jsx)(n.h3,{id:"3-investigar-c\xf3mo-se-aplica-dip-en-programaci\xf3n-funcional-investig\xe1-c\xf3mo-los-lenguajes-funcionales-logran-inversi\xf3n-de-dependencias-mediante-higher-order-functions-type-classes-haskellscala-y-el-reader-monad-pattern-son-estos-mecanismos-m\xe1s-o-menos-poderosos-que-las-interfaces-en-oop",children:'3. [Investigar] \xbfC\xf3mo se aplica DIP en programaci\xf3n funcional? Investig\xe1 c\xf3mo los lenguajes funcionales logran inversi\xf3n de dependencias mediante higher-order functions, type classes (Haskell/Scala), y el "Reader monad" pattern. \xbfSon estos mecanismos m\xe1s o menos poderosos que las interfaces en OOP?'}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"Respuesta"}),": En FP, DIP se implementa sin interfaces expl\xedcitas: (1) ",(0,i.jsx)(n.strong,{children:"Higher-order functions (HOF)"}),": en lugar de inyectar ",(0,i.jsx)(n.code,{children:"Database"})," (interfaz) se inyecta ",(0,i.jsx)(n.code,{children:"save: Order => IO[Unit]"})," (funci\xf3n). El componente de alto nivel recibe funciones que definen el comportamiento; el de bajo nivel provee funciones concretas. (2) ",(0,i.jsx)(n.strong,{children:"Type classes (Haskell)"}),": definen un contrato polim\xf3rfico sin herencia. ",(0,i.jsx)(n.code,{children:"class Monad m"})," define el contrato; ",(0,i.jsx)(n.code,{children:"instance Monad IO"})," lo implementa. El c\xf3digo de alto nivel trabaja con ",(0,i.jsx)(n.code,{children:"Monad m => ..."})," (abstracci\xf3n). Las implementaciones concretas son instancias de type class. (3) ",(0,i.jsx)(n.strong,{children:"Reader monad"})," (Scala Cats/ZIO, Haskell): ",(0,i.jsx)(n.code,{children:"Reader[Database, A]"})," es una computaci\xf3n que requiere un ",(0,i.jsx)(n.code,{children:"Database"})," para producir ",(0,i.jsx)(n.code,{children:"A"}),". La dependencia se pasa impl\xedcitamente a trav\xe9s de la m\xf3nada. El componente de alto nivel retorna ",(0,i.jsx)(n.code,{children:"Reader[Database, A]"})," sin ejecutar la dependencia. ",(0,i.jsx)(n.strong,{children:"Comparaci\xf3n con OOP"}),": Son M\xc1S poderosos en: (a) no requieren declarar interfaces expl\xedcitas (la funci\xf3n o type class es la abstracci\xf3n), (b) la composici\xf3n es natural (componer Reader monads, combinar type classes), (c) el polimorfismo param\xe9trico garantiza m\xe1s propiedades que el polimorfismo por subtipado. Son MENOS poderosos en: (a) el descubrimiento de la API es m\xe1s dif\xedcil (no hay una interfaz documentada, solo firmas de funciones dispersas), (b) el tooling de IDEs es m\xe1s d\xe9bil para type classes que para interfaces Java."]}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"Por qu\xe9"}),': Mark Seemann ("Dependency Injection in .NET") y Runar Bjarnason ("Functional Programming in Scala") exploran DIP en FP. La conclusi\xf3n: FP logra DIP con menos ceremonias (sin interfaces expl\xedcitas) pero requiere m\xe1s disciplina de documentaci\xf3n y tipos.']}),"\n",(0,i.jsx)(n.hr,{}),"\n",(0,i.jsx)(n.h3,{id:"4-investigar-c\xf3mo-funciona-el-service-provider-interface-spi-de-java-y-c\xf3mo-se-relaciona-con-dip-investig\xe1-javautilserviceloader-java-6-y-el-mecanismo-de-providers-en-java-9-modules-en-qu\xe9-se-diferencia-spi-de-di-para-implementar-dip",children:"4. [Investigar] \xbfC\xf3mo funciona el Service Provider Interface (SPI) de Java y c\xf3mo se relaciona con DIP? Investig\xe1 java.util.ServiceLoader (Java 6+) y el mecanismo de providers en Java 9+ modules. \xbfEn qu\xe9 se diferencia SPI de DI para implementar DIP?"}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"Respuesta"}),": Java SPI (ServiceLoader, desde Java 6) permite descubrir implementaciones de una interfaz en tiempo de ejecuci\xf3n escaneando el classpath. El m\xf3dulo de alto nivel define una interfaz (ej. ",(0,i.jsx)(n.code,{children:"java.sql.Driver"}),"); los m\xf3dulos de bajo nivel proveen implementaciones en ",(0,i.jsx)(n.code,{children:"META-INF/services/"}),". La relaci\xf3n con DIP: SPI implementa DIP a nivel de plataforma porque: (1) El cliente depende solo de la interfaz (DIP). (2) El descubrimiento de implementaciones es autom\xe1tico \u2014 el cliente no conoce las implementaciones concretas (DIP). (3) Agregar una implementaci\xf3n es agregar un JAR al classpath sin modificar c\xf3digo (OCP + DIP). Diferencia con DI: ",(0,i.jsx)(n.strong,{children:"DI"})," asume que ALGUIEN (contenedor, f\xe1brica) conoce todas las implementaciones y las inyecta expl\xedcitamente. ",(0,i.jsx)(n.strong,{children:"SPI"}),' permite que las implementaciones se registren a s\xed mismas \u2014 el cliente consulta el ServiceLoader y obtiene todas las implementaciones disponibles sin que nadie las "inyecte" expl\xedcitamente. SPI es DIP con descubrimiento impl\xedcito; DI es DIP con inyecci\xf3n expl\xedcita. SPI se usa en JDBC (drivers de BD), SLF4J (logging), JAXP (parsing XML). En Java 9+, el ',(0,i.jsx)(n.code,{children:"uses"})," en module-info consolida el SPI: el m\xf3dulo cliente declara ",(0,i.jsx)(n.code,{children:"uses DatabaseDriver"})," y los proveedores declaran ",(0,i.jsx)(n.code,{children:"provides DatabaseDriver with MySQLDriver"}),"."]}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"Por qu\xe9"}),": SPI es el mecanismo de extensi\xf3n de la plataforma Java. Es DIP sin framework externo: el JDK mismo provee el mecanismo de inversi\xf3n. La decisi\xf3n SPI vs DI depende de qui\xe9n controla el wiring: SPI = el proveedor se auto-registra; DI = un tercero (contenedor) cablea."]}),"\n",(0,i.jsx)(n.hr,{}),"\n",(0,i.jsx)(n.h3,{id:"5-conectar-la-clase-menciona-que-dip-habilita-la-arquitectura-hexagonal-ports--adapters-investig\xe1-a-fondo-el-trabajo-original-de-alistair-cockburn-2005-sobre-hexagonal-architecture-y-explic\xe1-c\xf3mo-dip-es-el-pegamento-que-hace-posible-la-inversi\xf3n-de-dependencias-entre-el-dominio-y-la-infraestructura",children:'5. [Conectar] La clase menciona que DIP habilita la arquitectura hexagonal (Ports & Adapters). Investig\xe1 a fondo el trabajo original de Alistair Cockburn (2005) sobre Hexagonal Architecture y explic\xe1 c\xf3mo DIP es el "pegamento" que hace posible la inversi\xf3n de dependencias entre el dominio y la infraestructura.'}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"Respuesta"}),': Alistair Cockburn propuso Hexagonal Architecture en 2005: la aplicaci\xf3n (dominio) est\xe1 en el centro, y toda interacci\xf3n externa pasa por "puertos" (interfaces) y "adaptadores" (implementaciones). DIP es el pegamento porque: (1) Los puertos SON las abstracciones de DIP definidas por el dominio: ',(0,i.jsx)(n.code,{children:"OrderRepository"}),", ",(0,i.jsx)(n.code,{children:"PaymentGateway"}),", ",(0,i.jsx)(n.code,{children:"NotificationPort"}),". (2) Los adaptadores SON las implementaciones concretas de DIP: ",(0,i.jsx)(n.code,{children:"MongoOrderRepository"}),", ",(0,i.jsx)(n.code,{children:"StripePaymentGateway"}),", ",(0,i.jsx)(n.code,{children:"EmailAdapter"}),'. (3) La dependencia de c\xf3digo fuente va de los adaptadores hacia los puertos (DIP: los detalles dependen de las abstracciones). El dominio NUNCA importa un adaptador. Cockburn lo llam\xf3 "ports and adapters" porque los puertos definen el contrato (DIP: abstracci\xf3n) y los adaptadores traducen (DIP: detalle). Lo que Martin llam\xf3 "Clean Architecture" (2012) es una refinaci\xf3n de Cockburn con DIP como principio central expl\xedcito: la "regla de dependencia" de Clean Architecture ("las dependencias de c\xf3digo fuente solo pueden apuntar hacia adentro") es DIP aplicado a todos los niveles. Sin DIP, Hexagonal Architecture colapsa: si el dominio importa ',(0,i.jsx)(n.code,{children:"MongoOrderRepository"})," en lugar de depender de ",(0,i.jsx)(n.code,{children:"OrderRepository"}),", el adaptador se filtra al centro."]}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"Por qu\xe9"}),": Cockburn y Martin convergieron independientemente en la misma arquitectura con diferentes nombres. Cockburn enfatiz\xf3 la testeabilidad (cambiar adaptadores para tests); Martin enfatiz\xf3 DIP como el mecanismo. Ambos reconocen que DIP es el principio que permite que el dominio sea independiente de la infraestructura."]}),"\n",(0,i.jsx)(n.hr,{}),"\n",(0,i.jsx)(n.h3,{id:"6-conectar-conect\xe1-dip-con-el-patr\xf3n-dependency-injection-usando-libraries-en-react-c\xf3mo-el-patr\xf3n-de-inversifyjs-para-typescriptreact-implementa-ioc--dip-en-frontend-compar\xe1-con-el-enfoque-de-context-api-de-la-clase",children:'6. [Conectar] Conect\xe1 DIP con el patr\xf3n "Dependency Injection" usando libraries en React. \xbfC\xf3mo el patr\xf3n de "InversifyJS" para TypeScript/React implementa IoC + DIP en frontend? Compar\xe1 con el enfoque de Context API de la clase.'}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"Respuesta"}),": InversifyJS es un contenedor IoC para TypeScript que implementa DIP con decorators similares a Spring: ",(0,i.jsx)(n.code,{children:"@injectable()"})," marca una clase como inyectable, ",(0,i.jsx)(n.code,{children:"@inject(IMailService)"})," declara dependencias, y un contenedor define bindings entre interfaces e implementaciones. Comparaci\xf3n con Context API de la clase: ",(0,i.jsx)(n.strong,{children:"Context API"})," es DIP manual: cada componente lee del contexto (equivalente a Service Locator). Las dependencias son impl\xedcitas \u2014 no se declaran en el constructor. ",(0,i.jsx)(n.strong,{children:"InversifyJS"})," es DIP expl\xedcito: las dependencias se declaran en el constructor con ",(0,i.jsx)(n.code,{children:"@inject"}),", y el contenedor las resuelve autom\xe1ticamente. Ventajas de InversifyJS: (a) dependencias expl\xedcitas en firma (como constructor injection en Spring), (b) scope management (singleton, transient, request), (c) interceptors/middleware al estilo AOP, (d) resoluci\xf3n autom\xe1tica de \xe1rboles de dependencia. Desventajas: (a) m\xe1s boilerplate que Context API (decorators, configuraci\xf3n de contenedor), (b) menos idiom\xe1tico en React (la comunidad prefiere hooks + Context), (c) la resoluci\xf3n de dependencias es en runtime (decorators), no en build-time (como Dagger). Ambos cumplen DIP: el componente depende de ",(0,i.jsx)(n.code,{children:"IMailService"}),", no de ",(0,i.jsx)(n.code,{children:"SmtpMailService"}),". La elecci\xf3n depende de la escala: Context API para aplicaciones peque\xf1as/medianas (menos overhead), InversifyJS para aplicaciones grandes con muchas dependencias (mejor gesti\xf3n de scopes y vida \xfatil)."]}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"Por qu\xe9"}),": InversifyJS (Remo Jansen, 2015) trae el patr\xf3n Spring al ecosistema TypeScript. Es la demostraci\xf3n de que DIP y IoC son independientes del lenguaje: si ten\xe9s interfaces y constructores, pod\xe9s implementar DIP con un contenedor."]}),"\n",(0,i.jsx)(n.hr,{}),"\n",(0,i.jsx)(n.h3,{id:"7-conectar-relacion\xe1-dip-con-el-concepto-de-test-doubles-gerard-meszaros-xunit-test-patterns-2007-por-qu\xe9-sin-dip-no-pod\xe9s-usar-stubs-mocks-o-fakes-efectivamente-explic\xe1-c\xf3mo-cada-tipo-de-test-double-requiere-un-nivel-diferente-de-dip",children:'7. [Conectar] Relacion\xe1 DIP con el concepto de "Test Doubles" (Gerard Meszaros, "xUnit Test Patterns", 2007). \xbfPor qu\xe9 sin DIP no pod\xe9s usar stubs, mocks o fakes efectivamente? Explic\xe1 c\xf3mo cada tipo de test double requiere un nivel diferente de DIP.'}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"Respuesta"}),": Meszaros clasific\xf3 test doubles en: ",(0,i.jsx)(n.strong,{children:"Dummy"})," (no se usa), ",(0,i.jsx)(n.strong,{children:"Stub"})," (retorna valores prefijados), ",(0,i.jsx)(n.strong,{children:"Spy"})," (registra llamadas), ",(0,i.jsx)(n.strong,{children:"Mock"})," (verifica expectativas), ",(0,i.jsx)(n.strong,{children:"Fake"})," (implementaci\xf3n alternativa ligera, ej. DB en memoria). Sin DIP, ninguno es viable porque: la clase bajo test instancia directamente ",(0,i.jsx)(n.code,{children:"new MySQLDatabase()"}),". No hay punto de inyecci\xf3n para insertar el test double. Con DIP, la clase recibe ",(0,i.jsx)(n.code,{children:"Database"})," (interfaz) por constructor: se puede inyectar cualquier test double. Niveles de DIP requeridos: ",(0,i.jsx)(n.strong,{children:"Stub"})," solo necesita que la dependencia sea una interfaz (nivel m\xednimo de DIP: una interfaz con un m\xe9todo). ",(0,i.jsx)(n.strong,{children:"Mock"})," necesita interfaz para que Mockito pueda generar el proxy. ",(0,i.jsx)(n.strong,{children:"Fake"})," necesita interfaz + una segunda implementaci\xf3n (nivel medio de DIP: abstracci\xf3n con al menos dos implementaciones). ",(0,i.jsx)(n.strong,{children:"Spy"})," necesita lo mismo que mock. Dummy no requiere DIP (no se usa) pero se beneficia de \xe9l (inyectar null en lugar de instanciar). Conclusi\xf3n: DIP es el habilitador universal de test doubles. Un sistema sin DIP es un sistema sin test doubles efectivos, y por lo tanto sin pruebas unitarias r\xe1pidas. Meszaros impl\xedcitamente asume DIP porque todos sus patrones de test doubles requieren que la dependencia sea inyectable."]}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"Por qu\xe9"}),": La conexi\xf3n Meszaros-Martin: los test doubles son la herramienta pr\xe1ctica; DIP es el principio que los hace posibles. Sin DIP, cada prueba es de integraci\xf3n (lenta, fr\xe1gil)."]}),"\n",(0,i.jsx)(n.hr,{}),"\n",(0,i.jsx)(n.h3,{id:"8-cuestionar-es-dip-siempre-beneficioso-o-puede-llevar-a-una-arquitectura-de-cebolla-podrida-investig\xe1-cr\xedticas-sobre-sistemas-donde-cada-clase-tiene-una-interfaz-cada-m\xe9todo-tiene-una-abstracci\xf3n-y-el-grafo-de-dependencias-es-tan-complejo-que-entender-el-flujo-requiere-herramientas-de-visualizaci\xf3n-d\xf3nde-est\xe1-el-l\xedmite-de-la-inversi\xf3n",children:'8. [Cuestionar] \xbfEs DIP siempre beneficioso o puede llevar a una "arquitectura de cebolla podrida"? Investig\xe1 cr\xedticas sobre sistemas donde cada clase tiene una interfaz, cada m\xe9todo tiene una abstracci\xf3n, y el grafo de dependencias es tan complejo que entender el flujo requiere herramientas de visualizaci\xf3n. \xbfD\xf3nde est\xe1 el l\xedmite de la inversi\xf3n?'}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"Respuesta"}),': Cr\xedticos como John Ousterhout ("A Philosophy of Software Design") y Yegor Bugayenko se\xf1alan que DIP mal aplicado produce: (1) ',(0,i.jsx)(n.strong,{children:"Indirecci\xf3n innecesaria"}),": cada clase tiene una interfaz correspondiente que solo existe para cumplir DIP, no porque haya m\xfaltiples implementaciones. Si ",(0,i.jsx)(n.code,{children:"OrderService"})," es la \xdaNICA implementaci\xf3n de ",(0,i.jsx)(n.code,{children:"IOrderService"}),', la interfaz es ruido. Ousterhout: "los m\xf3dulos profundos tienen interfaces peque\xf1as e implementaciones complejas". El anti-patr\xf3n DIP es "interfaces grandes e implementaciones triviales" \u2014 cada m\xe9todo de ',(0,i.jsx)(n.code,{children:"IOrderService"})," delega a ",(0,i.jsx)(n.code,{children:"OrderService"}),". (2) ",(0,i.jsx)(n.strong,{children:"Arquitectura de cebolla podrida"}),": cuando las capas de abstracci\xf3n se multiplican (Controller \u2192 IOrderService \u2192 IOrderRepository \u2192 IDatabase), seguir el flujo requiere abrir 8 archivos. El costo cognitivo supera el beneficio de desacoplamiento. (3) ",(0,i.jsx)(n.strong,{children:"YAGNI violado"}),": abstracciones creadas para cambios hipot\xe9ticos que nunca ocurren. El l\xedmite: DIP debe aplicarse a dependencias VOL\xc1TILES (BD, APIs externas, servicios cloud) pero no a dependencias ESTABLES (value objects, utilidades del lenguaje, l\xf3gica de dominio interna que es inherentemente acoplada). La regla: solo invert\xed dependencias que: (a) tienen al menos DOS implementaciones en producci\xf3n, o (b) son de infraestructura (BD, mensajer\xeda, HTTP), o (c) impiden el testing r\xe1pido. Para todo lo dem\xe1s, el acoplamiento directo es m\xe1s simple y no tiene costo."]}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"Por qu\xe9"}),': Ousterhout (2018) dedica un cap\xedtulo entero a "Define Errors Out of Existence" y "Design it Twice" donde argumenta contra las abstracciones prematuras. Martin coincide parcialmente: DIP es para dependencias vol\xe1tiles, no para todo.']}),"\n",(0,i.jsx)(n.hr,{}),"\n",(0,i.jsx)(n.h3,{id:"9-cuestionar-dip-o-service-locator-martin-fowler-2004-argument\xf3-que-service-locator-es-un-anti-patr\xf3n-comparado-con-dependency-injection-pero-frameworks-como-android-con-hiltdagger-y-algunos-sistemas-legacy-usan-service-locator-exitosamente-es-realmente-un-anti-patr\xf3n-o-una-alternativa-v\xe1lida-en-ciertos-contextos",children:'9. [Cuestionar] \xbfDIP o "Service Locator"? Martin Fowler (2004) argument\xf3 que Service Locator es un anti-patr\xf3n comparado con Dependency Injection. Pero frameworks como Android (con Hilt/Dagger) y algunos sistemas legacy usan Service Locator exitosamente. \xbfEs realmente un anti-patr\xf3n o una alternativa v\xe1lida en ciertos contextos?'}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"Respuesta"}),": Fowler en 2004 describi\xf3 Service Locator como la alternativa a DI donde el objeto pide sus dependencias a un registro (",(0,i.jsx)(n.code,{children:"ServiceLocator.resolve(IDatabase.class)"}),") en lugar de recibirlas por constructor. Cr\xedticas de Fowler: (1) Dependencias ocultas: no pod\xe9s saber qu\xe9 necesita una clase mirando su constructor \u2014 ten\xe9s que leer su cuerpo. (2) Acoplamiento al Service Locator: todas las clases dependen de la clase ",(0,i.jsx)(n.code,{children:"ServiceLocator"}),". (3) Dificultad de testing: necesit\xe1s configurar el Service Locator global antes de cada test. ",(0,i.jsx)(n.strong,{children:"Defensa del Service Locator"}),": (1) En Android, Hilt/Dagger generan c\xf3digo que act\xfaa como Service Locator compilado, no runtime \u2014 no hay penalidad de performance. (2) Para sistemas legacy donde no se puede refactorizar todo a constructor injection, Service Locator es un paso intermedio pragm\xe1tico. (3) En lenguajes sin contenedor IoC (C, Go), Service Locator es la \xfanica opci\xf3n. (4) Kevlin Henney argumenta que Service Locator es DIP v\xe1lido si el locator retorna interfaces: el cliente sigue dependiendo de la abstracci\xf3n; solo cambia el mecanismo de obtenci\xf3n. ",(0,i.jsx)(n.strong,{children:"Conclusi\xf3n"}),": Service Locator no es inherentemente malo; es inferior a DI en testabilidad y transparencia. Pero en contextos donde DI no es viable (ausencia de framework, limitaciones del lenguaje), Service Locator con interfaz es una aplicaci\xf3n v\xe1lida de DIP (aunque sub\xf3ptima)."]}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"Por qu\xe9"}),': Fowler mismo matiz\xf3 su posici\xf3n: "Service Locator is not inherently evil, but it has downsides that DI avoids". La industria mobile (Android con Dagger/Hilt que genera Service Locators en compile-time) demostr\xf3 que la versi\xf3n compilada del patr\xf3n resuelve las principales objeciones.']}),"\n",(0,i.jsx)(n.hr,{}),"\n",(0,i.jsx)(n.h3,{id:"10-cuestionar-es-dip-el-principio-m\xe1s-costoso-de-solid-investig\xe1-el-trade-off-entre-inversi\xf3n-de-dependencias-y-performancecarga-cognitiva-hay-dominios-ej-sistemas-embebidos-videojuegos-high-frequency-trading-donde-dip-activamente-perjudica",children:'10. [Cuestionar] \xbfEs DIP el principio m\xe1s "costoso" de SOLID? Investig\xe1 el trade-off entre inversi\xf3n de dependencias y performance/carga cognitiva. \xbfHay dominios (ej. sistemas embebidos, videojuegos, high-frequency trading) donde DIP activamente perjudica?'}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"Respuesta"}),": DIP tiene costos reales: (1) ",(0,i.jsx)(n.strong,{children:"Performance"}),": cada llamada por interfaz en Java implica despacho virtual (vtable lookup). En sistemas de alta frecuencia (HFT, trading), la diferencia entre llamado directo y llamado virtual puede ser inaceptable. (2) ",(0,i.jsx)(n.strong,{children:"Memoria"}),": objetos inyectados + proxies + contenedor IoC consumen heap. (3) ",(0,i.jsx)(n.strong,{children:"Carga cognitiva"}),": la indirecci\xf3n hace que el debugging sea m\xe1s dif\xedcil (stack traces m\xe1s profundas, necesidad de tooling de visualizaci\xf3n de dependencias). (4) ",(0,i.jsx)(n.strong,{children:"Build time"}),": sistemas con miles de interfaces compilan m\xe1s lento. Dominios donde DIP perjudica: ",(0,i.jsx)(n.strong,{children:"Videojuegos"}),": ECS (Entity Component Systems) evitan herencia/interfaces por performance. En Unity, ",(0,i.jsx)(n.code,{children:"GameObject.GetComponent&#x3C;T>()"})," es m\xe1s costoso que acceso directo. Los motores de juego optimizan para data locality (cache-friendly), no para desacoplamiento. ",(0,i.jsx)(n.strong,{children:"Sistemas embebidos"}),": con restricciones de memoria (64KB RAM), cada vtable es overhead. ",(0,i.jsx)(n.strong,{children:"HFT"}),': cada nanosegundo cuenta; la indirecci\xf3n de interfaz es inaceptable. Robert Nystrom ("Game Programming Patterns", 2014) y Mike Acton (Data-Oriented Design) argumentan que SOLID asume recursos abundantes; en sistemas con restricciones extremas, la simplicidad y performance dominan sobre la extensibilidad. Martin reconoce esto: SOLID es para software empresarial con vida \xfatil larga y requisitos cambiantes, no para todo el software.']}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"Por qu\xe9"}),": Martin en Clean Architecture aclara que SOLID es para sistemas donde el costo de mantenimiento domina sobre el costo de hardware. En sistemas donde la performance es el requisito principal, DIP es un lujo que no todos pueden pagar."]})]})}function p(e={}){const{wrapper:n}={...(0,s.R)(),...e.components};return n?(0,i.jsx)(n,{...e,children:(0,i.jsx)(l,{...e})}):l(e)}},28453(e,n,a){a.d(n,{R:()=>r,x:()=>c});var o=a(96540);const i={},s=o.createContext(i);function r(e){const n=o.useContext(s);return o.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function c(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:r(e.components),o.createElement(s.Provider,{value:n},e.children)}}}]);